h2 {
  font-size: clamp(1.5rem, 3.2vw, 2.5rem);
  font-family: "Playfair Display", Georgia, serif;
}
.lead { font-size: 1.1rem; color: rgba(255,255,255,.92); max-width: 60ch; }

.btn {
  display: inline-block;
  margin-top: 16px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
