.card h3 { margin-bottom: 10px; font-size: 1.2rem; }
.meta { font-size: .85rem; color: var(--gray-500); }
.link-arrow { color: var(--teal); font-weight: 600; }

.announcement {
  background: var(--navy);
  color: var(--white);
