  flex-direction: column;
  gap: 8px;
}
.tab-btn {
  border: 0;
  background: transparent;
  text-align: left;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--gray-700);
  padding: 12px;
  border-radius: 8px;
